{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Clopenthixol, which shares the same 2-chloro-thioxanthene core and exocyclic propylidene attachment as the query, has an absolute oral bioavailability of 40-60% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Flupenthixol, another close thioxanthene analogue, has a mean systemic availability of 55% (range 48-60%) after oral tablets versus IV, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Cyclobenzaprine, a tricyclic with the same dimethylaminopropylidene side chain, has mean oral bioavailability 0.55 (90% CI 0.51-0.60), supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Amitriptyline, a tricyclic antidepressant with the same dimethylaminopropylidene side chain, has absolute oral bioavailability 47.7 ± 11% in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Doxepin, a tricyclic with the same side chain, has mean absolute oral bioavailability 29%, still above the 20% threshold, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Prochlorperazine, a phenothiazine with a piperazine side chain, has low absolute oral bioavailability of 12.5 ± 4.3%, but its different core and side-chain class limits transfer to the thioxanthene query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C43"],
      "claim": "Zotepine, a dibenzothiepine with a dimethylaminoethoxy side chain, has very low bioavailability of 7-13%, but differs from the query's thioxanthene propylidene structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is chlorprothixene, a 2-chloro-thioxanthene with a dimethylaminopropylidene side chain. The closest thioxanthene analogues, clopenthixol and flupenthixol, have absolute oral bioavailability of 40-60%, well above the 20% threshold. Other tricyclics with the same side chain also exceed 20%. Low-bioavailability phenothiazine and dibenzothiepine analogues are structurally distinct and do not override the close-analogue evidence. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for chlorprothixene is present in the provided evidence set.",
    "First-pass metabolism variability could affect the exact F value, though the closest analogues consistently exceed the 20% threshold.",
    "Low-F analogues show that core and side-chain changes can strongly alter bioavailability, so exact quantitative extrapolation remains uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

